/*
 * REFERENCE IMAGES PAGE RENDERER — drives reference-images.html. Loads
 * reference/sections-index.js + every section's data.js (generated by
 * scripts/generate-reference-data.js from whatever's in reference/<id>/assets/),
 * and renders each as a titled Pinterest-style masonry block, in order.
 */
(function () {
  "use strict";

  var P = window.PROJECT;
  var C = window.SiteCommon;

  var flatImages = []; // every image across every section, in display order — lightbox nav flows through all of them
  var lightboxIndex = 0;

  document.addEventListener("DOMContentLoaded", init);

  function init() {
    C.renderChrome(P, "./");
    // No hero image/video sits behind this page's header (unlike the homepage
    // and version subpages), so the header's default transparent/white-text
    // state — designed for contrast against a dark hero — would be unreadable
    // against the plain page-banner background. Force the "scrolled" (solid
    // background, dark text) look permanently instead of scroll-toggling it.
    document.getElementById("siteHeader").classList.add("is-scrolled");
    C.bindNavToggle();
    C.bindScrollProgress();
    C.bindReveal();
    C.bindGlobalEscape();
    bindLightbox();

    document.title = "Reference Images | " + P.studio.name;

    window.VersionLoader.loadAll("./reference/", "sections-index.js", "SECTION_IDS")
      .then(function (ids) {
        render(ids);
        C.bindReveal(); // pick up the freshly-added section/image elements
      })
      .catch(function (err) {
        document.getElementById("sectionsContainer").textContent =
          "Couldn't load reference sections (" + err.message + ").";
      });
  }

  function assetUrl(sectionId, rel) {
    return "./reference/" + sectionId + "/" + rel;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function render(ids) {
    var container = document.getElementById("sectionsContainer");
    var emptyNote = document.getElementById("noSectionsNote");
    var sections = ids.map(function (id) { return window.SECTIONS[id]; }).filter(Boolean);

    if (!sections.length) {
      emptyNote.hidden = false;
      return;
    }
    emptyNote.hidden = true;

    sections.forEach(function (section, i) {
      var sectionEl = document.createElement("section");
      sectionEl.className = "ref-section" + (i % 2 === 1 ? " ref-section-alt" : "");

      var noteHtml = section.note ? "<p>" + escapeHtml(section.note) + "</p>" : "";
      sectionEl.innerHTML =
        '<div class="container">' +
          '<div class="section-head" data-reveal>' +
            '<div><p class="eyebrow">Reference</p><h2>' + escapeHtml(section.title) + "</h2></div>" +
            noteHtml +
          "</div>" +
          '<div class="masonry"></div>' +
        "</div>";
      container.appendChild(sectionEl);

      var masonryEl = sectionEl.querySelector(".masonry");
      (section.images || []).forEach(function (img) {
        var flatIndex = flatImages.length;
        flatImages.push({
          sectionTitle: section.title,
          src: assetUrl(section.id, img.src),
          caption: img.caption
        });

        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "masonry-item";
        btn.setAttribute("data-reveal", "");
        btn.innerHTML = '<img src="' + assetUrl(section.id, img.src) + '" alt="' +
          escapeHtml(section.title + " — " + img.caption) + '" loading="lazy">';
        btn.addEventListener("click", function () { openLightbox(flatIndex); });
        masonryEl.appendChild(btn);
      });
    });
  }

  function openLightbox(index) {
    lightboxIndex = index;
    renderLightbox();
    C.openModal(document.getElementById("lightbox"));
  }

  function renderLightbox() {
    if (!flatImages.length) return;
    lightboxIndex = ((lightboxIndex % flatImages.length) + flatImages.length) % flatImages.length;
    var current = flatImages[lightboxIndex];
    document.getElementById("lightboxImg").src = current.src;
    document.getElementById("lightboxImg").alt = current.sectionTitle + " — " + current.caption;
    document.getElementById("lightboxLabel").textContent =
      current.sectionTitle + " — " + current.caption + " (" + (lightboxIndex + 1) + "/" + flatImages.length + ")";
  }

  function bindLightbox() {
    var modal = document.getElementById("lightbox");
    document.getElementById("lightboxClose").addEventListener("click", function () { C.closeModal(modal); });
    modal.addEventListener("click", function (e) { if (e.target === modal) C.closeModal(modal); });
    document.getElementById("lightboxPrev").addEventListener("click", function () {
      lightboxIndex -= 1;
      renderLightbox();
    });
    document.getElementById("lightboxNext").addEventListener("click", function () {
      lightboxIndex += 1;
      renderLightbox();
    });
    document.addEventListener("keydown", function (e) {
      if (!modal.classList.contains("is-open")) return;
      if (e.key === "ArrowLeft") { lightboxIndex -= 1; renderLightbox(); }
      if (e.key === "ArrowRight") { lightboxIndex += 1; renderLightbox(); }
    });
  }
})();
